#[path="../programs/notepad/document.rs"]mod document;
use document::*;
#[test]fn full_document_navigation_undo_and_redo(){let mut d=Document::new();assert!(d.load(&vec![b'x';LIMIT]));assert!(!d.replace(0,0,b"a"));assert_eq!(d.length,LIMIT);assert!(d.replace(10,11,b"a"));assert!(d.replace(11,12,b"b"));assert!(d.replace(12,13,b"c"));d.undo();d.undo();d.undo();assert_eq!(&d.data[10..13],b"xxx");assert!(!d.dirty());d.redo();d.redo();d.redo();assert_eq!(&d.data[10..13],b"abc");assert!(d.dirty());assert!(d.mark_saved());assert!(!d.dirty());}
#[test]fn load_failures_preserve_data_and_normalization_is_bounded(){let mut d=Document::new();assert!(d.load(b"a\r\nb\tc"));assert_eq!(&d.data,b"a\nb    c");assert!(!d.load(&vec![9;LIMIT]));assert!(!d.load(b"bad\0"));assert_eq!(&d.data,b"a\nb    c");assert!(normalize(&vec![b'x';LIMIT]).is_some());assert!(normalize(&vec![b'x';LIMIT+1]).is_none());}
#[test]fn newline_heavy_index_and_resize_preserve_offsets(){let mut d=Document::new();assert!(d.load(&vec![10;LIMIT]));assert_eq!(d.line_count(),LIMIT+1);assert_eq!(d.position(LIMIT),(LIMIT,0));assert_eq!(d.offset(LIMIT,0),LIMIT);assert_eq!(d.screen_row_n::<96>(LIMIT),[32;96]);assert!(d.load(&vec![b'x';1000]));d.set_width(94);assert_eq!(d.position(100),(1,6));assert_eq!(d.offset(1,6),100);assert_eq!(d.selection_span(0,90,100),(90,94));d.set_width(78);assert_eq!(d.position(100),(1,22));}
#[test]fn editing_after_undo_discards_redo_and_history_is_bounded(){let mut d=Document::new();for b in b"abcdef"{let n=d.length;assert!(d.replace(n,n,&[*b]));}for _ in 0..8{d.undo();}assert_eq!(&d.data,b"ab");assert!(d.replace(2,2,b"z"));d.redo();assert_eq!(&d.data,b"abz");d.clear();assert_eq!(d.line_count(),1);assert!(!d.dirty());}
